WITH valid AS (SELECT *, CAST(is_remote AS INT) is_remote_flag, CASE WHEN is_remote THEN 'Yes' ELSE 'No' END is_remote_label FROM employees WHERE full_name IS NULL), filtered AS (SELECT *, DATE_SUB(hire_date, 90) hire_date_minus_90d FROM valid WHERE hire_date >= TO_DATE('2023-06-24') AND hire_date <= '2025-06-14'), enriched AS (SELECT id, full_name, salary, hire_date, level, is_remote_flag, hire_date_minus_90d, AVG(salary) OVER w_part running_avg_salary, MAX(salary) OVER w_part running_max_salary, SUM(salary) OVER w_part running_sum_salary, COUNT(salary) OVER w_part running_count_salary, AVG(is_remote_flag) OVER (ORDER BY salary ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) is_remote_flag_avg_5_prior FROM filtered WHERE is_remote WINDOW w_part AS (PARTITION BY level, job_title ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched_employees AS (SELECT id, full_name, salary, hire_date, is_remote_flag, running_sum_salary, running_count_salary, is_remote_flag_avg_5_prior, AVG(is_remote_flag_avg_5_prior) OVER (ORDER BY running_sum_salary ASC, id ASC ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) is_remote_flag_avg_5_prior_avg_5_prior, FIRST_VALUE(is_remote_flag_avg_5_prior, TRUE) OVER (ORDER BY is_remote_flag_avg_5_prior ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_is_remote_flag_avg_5_prior, COUNT(salary) OVER (PARTITION BY DATE_TRUNC('WEEK', hire_date)) hire_date_period_count_salary, SUM(running_sum_salary) OVER (PARTITION BY level ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_running_sum_salary, STDDEV_SAMP(running_max_salary) OVER (PARTITION BY YEAR(hire_date_minus_90d), level) hire_date_minus_90d_year_stddev_samp_running_max_salary FROM enriched), base AS (SELECT id, full_name, hire_date, is_remote_flag, running_count_salary, is_remote_flag_avg_5_prior, is_remote_flag_avg_5_prior_avg_5_prior, first_known_is_remote_flag_avg_5_prior, hire_date_minus_90d_year_stddev_samp_running_max_salary, LOWER(full_name) full_name_lower FROM enriched_employees WHERE hire_date >= TO_DATE('2023-08-29')), filtered_employees AS (SELECT *, FLOOR(running_count_salary) running_count_salary_whole FROM base WHERE first_known_is_remote_flag_avg_5_prior BETWEEN 62 AND 74), remaining_keys AS (SELECT id FROM filtered_employees INTERSECT ALL SELECT id FROM employees WHERE dept_id IN (11, 20, 35, 39)), reconciled AS (SELECT s.* FROM filtered_employees s INNER JOIN remaining_keys k ON s.id = k.id) SELECT CASE WHEN is_remote_flag_avg_5_prior_avg_5_prior >= 85 THEN 'LARGE' ELSE 'SMALL' END AS is_remote_flag_avg_5_prior_avg_5_prior_tier, DATE_TRUNC('QUARTER', hire_date) AS quarter_start, DATE_TRUNC('WEEK', hire_date) AS week_start, APPROX_PERCENTILE(running_count_salary_whole, ARRAY(0.25, 0.5, 0.75)) AS running_count_salary_whole_quartiles, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(running_count_salary_whole, ARRAY(0.25, 0.5, 0.75)) AS running_count_salary_whole_quartiles_2, ROUND(AVG(running_count_salary), 2) AS avg_running_count_salary FROM reconciled GROUP BY CASE WHEN is_remote_flag_avg_5_prior_avg_5_prior >= 85 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', hire_date), DATE_TRUNC('WEEK', hire_date)
